export const BackgroundAnimation: React.FC = () => {
  // Generate random circles
  const circles = Array.from({ length: 6 }).map((_, i) => ({
    id: i,
    width: Math.random() * 300 + 100,
    height: Math.random() * 300 + 100,
    x: Math.random() * 100,
    y: Math.random() * 100,
    duration: Math.random() * 20 + 10,
