  return (
    <div className="fixed inset-0 overflow-hidden pointer-events-none -z-10">
      {/* Light Mode Blobs (Warm/Cool mix) */}
      <div className="dark:hidden w-full h-full absolute inset-0 bg-slate-50">
        {circles.map((circle) => (
          <motion.div
            key={`light-${circle.id}`}
            className="absolute rounded-full mix-blend-multiply filter blur-3xl opacity-30"
            style={{
              width: circle.width,
              height: circle.height,
              backgroundColor: circle.id % 2 === 0 ? '#bae6fd' : '#e0f2fe', // sky-200 / sky-100
              top: `${circle.y}%`,
              left: `${circle.x}%`,
            }}
            animate={{
              x: [0, Math.random() * 100 - 50, 0],
              y: [0, Math.random() * 100 - 50, 0],
              scale: [1, 1.2, 1],
