      </div>

      {/* Dark Mode Blobs (Deep/Vibrant) */}
      <div className="hidden dark:block w-full h-full absolute inset-0 bg-slate-950">
         {circles.map((circle) => (
          <motion.div
            key={`dark-${circle.id}`}
            className="absolute rounded-full mix-blend-screen filter blur-[80px] opacity-20"
            style={{
              width: circle.width,
              height: circle.height,
              backgroundColor: circle.id % 2 === 0 ? '#0ea5e9' : '#6366f1', // primary / indigo
              top: `${circle.y}%`,
              left: `${circle.x}%`,
