import { GoogleGenAI } from "@google/genai";
import { PORTFOLIO_DATA, EXPERIENCE, PROJECTS, SKILLS } from '../constants';

const API_KEY = process.env.API_KEY || '';

// Construct a system prompt based on the portfolio data
const SYSTEM_INSTRUCTION = `
You are an AI assistant for ${PORTFOLIO_DATA.name}'s portfolio website.
Your role is to answer questions about Ajaykumar's professional background, skills, and projects in a professional, friendly, and concise manner.

Here is the context about Ajaykumar:
Name: ${PORTFOLIO_DATA.name}
Title: ${PORTFOLIO_DATA.title}
About: ${PORTFOLIO_DATA.about}

Skills:
${SKILLS.map(s => `- ${s.name} (${s.category})`).join('\n')}

Experience:
${EXPERIENCE.map(e => `- ${e.role} at ${e.company} (${e.period}): ${e.description.join(' ')}`).join('\n')}

Projects:
${PROJECTS.map(p => `- ${p.title}: ${p.description} (Tech: ${p.tags.join(', ')})`).join('\n')}

If asked about contact info, provide: ${PORTFOLIO_DATA.email} or LinkedIn: ${PORTFOLIO_DATA.linkedin}.
If asked a question not related to Ajaykumar's professional life, politely steer the conversation back to his portfolio or answer generally if appropriate but brief.
Keep answers under 100 words unless detailed explanation is requested.
`;

let aiClient: GoogleGenAI | null = null;

export const initializeGenAI = () => {
  if (!API_KEY) {
    console.warn("Gemini API Key is missing. AI features will not work.");
    return null;
  }
  if (!aiClient) {
    aiClient = new GoogleGenAI({ apiKey: API_KEY });
  }
  return aiClient;
};

export const sendMessageToGemini = async (message: string, history: { role: 'user' | 'model', text: string }[]) => {
  const client = initializeGenAI();
  if (!client) {
    throw new Error("API Key not configured");
  }

  try {
    const chat = client.chats.create({
      model: 'gemini-3-flash-preview',
      config: {
        systemInstruction: SYSTEM_INSTRUCTION,
      },
      history: history.map(h => ({
        role: h.role,
        parts: [{ text: h.text }]
      }))
    });

    const result = await chat.sendMessage({ message });
    return result.text;
  } catch (error) {
    console.error("Error calling Gemini API:", error);
    throw error;
  }
};

