                        Code
                      </Button>
                    )}
                    {project.link && (
                      <Button 
                        size="small" 
                        startIcon={<ExternalLink size={16} />} 
                        href={project.link}
                        target="_blank"
                        sx={{ color: 'text.secondary', '&:hover': { color: 'primary.main' } }}
                      >
                        Live Demo
                      </Button>
                    )}
                  </CardActions>
                </Card>
              </motion.div>
            </Grid>
          ))}
        </Grid>
      </Container>
    </Box>
  );
};

