import React, { useMemo } from 'react';
import { motion } from 'framer-motion';
import { Box, useTheme } from '@mui/material';

export const BackgroundAnimation: React.FC = () => {
  const theme = useTheme();

  // Generate random circles once and store them. 
  // This prevents them from resetting/jumping on every re-render or theme change.
  const circles = useMemo(() => Array.from({ length: 6 }).map((_, i) => ({
    id: i,
    width: Math.random() * 300 + 100,
    height: Math.random() * 300 + 100,
    x: Math.random() * 100,
    y: Math.random() * 100,
    duration: Math.random() * 20 + 10,
    delay: Math.random() * 5,
  })), []);

  const isDark = theme.palette.mode === 'dark';

  return (
    <Box 
      sx={{ 
        position: 'fixed', 
        inset: 0, 
        zIndex: -1, 
        overflow: 'hidden', 
        bgcolor: 'background.default',
        pointerEvents: 'none',
        transition: 'background-color 0.3s ease'
      }}
    >
      {circles.map((circle) => (
        <motion.div
          key={circle.id}
          style={{
            position: 'absolute',
            width: circle.width,
            height: circle.height,
            borderRadius: '50%',
            top: `${circle.y}%`,
            left: `${circle.x}%`,
            filter: isDark ? 'blur(80px)' : 'blur(40px)',
            backgroundColor: circle.id % 2 === 0 ? theme.palette.primary.main : theme.palette.secondary.main,
            opacity: isDark ? 0.15 : 0.08,
            mixBlendMode: isDark ? 'screen' : 'multiply'
          }}
          animate={{
            x: [0, Math.random() * 100 - 50, 0],
            y: [0, Math.random() * 100 - 50, 0],
            scale: [1, 1.2, 1],
          }}
          transition={{
            duration: circle.duration,
            repeat: Infinity,
            ease: "easeInOut",
            delay: circle.delay
          }}
        />
      ))}
    </Box>
  );
};

